    {
        AI_gpst_CurrentFunction->varsResolved = 1;
        get_object_go_get_i_bit_univVars = AI_ul_RealResolveOneRefObject(0x71003FF9u);
        AI2C_ResolveBuffer(
            &get_object_go_get_i_bit_univVars_Flag_speciaux_sauve,
            (void*)get_object_go_get_i_bit_univVars,
            4488);
    }
    if (v1->des_SF_destroy_on_load <= 0)
        v1->i_bit = 0;
    else
        v1->i_bit = AI_EvalFunc_ARRBitTest_C(
            (int*)(get_object_go_get_i_bit_univVars_Flag_speciaux_sauve + 4),
            v1->des_SF_destroy_on_load);
    if (v1->des_SF_inverse_status)
    {
        if (v1->i_bit)
            v1->i_bit = 0;
        else
            v1->i_bit = 1;
    }
